def _resample(points, count: int = 24):
    """Resample points evenly along a polyline so distance is independent of point count."""
    if len(points) < 2:
        return list(points) * count
    lengths = [0.0]
    for (x1, y1), (x2, y2) in itertools.pairwise(points):
        lengths.append(lengths[-1] + ((x2 - x1) ** 2 + (y2 - y1) ** 2) ** 0.5)
    total = lengths[-1] or 1.0
    out = []
    for step in range(count):
        target = total * step / (count - 1)
        for i in range(len(lengths) - 1):
            if lengths[i] <= target <= lengths[i + 1]:
                index = i
                break
        else:
            index = len(points) - 2
        span = lengths[index + 1] - lengths[index] or 1.0
        ratio = min(1.0, max(0.0, (target - lengths[index]) / span))
        x1, y1 = points[index]
        x2, y2 = points[index + 1]
        out.append((x1 + (x2 - x1) * ratio, y1 + (y2 - y1) * ratio))
    return out


def _normalize(glyph):
    xs = [x for stroke in glyph for x, _ in stroke]
    ys = [y for stroke in glyph for _, y in stroke]
    width = max(xs) - min(xs) or 1.0
    height = max(ys) - min(ys) or 1.0
    return [
        _resample([((x - min(xs)) / width, (y - min(ys)) / height) for x, y in stroke])
        for stroke in glyph
    ]


def _stroke_distance(a, b) -> float:
    """Distance between two strokes allowing reversed direction or phase shift if closed."""
    count = len(a)
    if len(b) != count:
        return 1.0
    best = 1.0
    is_closed = ((b[0][0] - b[-1][0]) ** 2 + (b[0][1] - b[-1][1]) ** 2) ** 0.5 < 0.15
    candidates = [b, b[::-1]]
    if is_closed:
        for cand in candidates:
            for shift in range(count):
                shifted = cand[shift:] + cand[:shift]
                cost = (
                    sum(
                        ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5
                        for (x1, y1), (x2, y2) in zip(a, shifted, strict=False)
                    )
                    / count
                )
                best = min(best, cost)
    else:
        for cand in candidates:
            cost = (
                sum(
                    ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5
                    for (x1, y1), (x2, y2) in zip(a, cand, strict=False)
                )
                / count
            )
            best = min(best, cost)
    return best


def _shape_distance(a, b) -> float:
    """Shape distance between two normalized glyphs via greedy minimum stroke matching."""
    if len(a) != len(b):
        return 1.0
    remaining = list(b)
    total = 0.0
    for stroke in a:
        costs = [
            (min(_stroke_distance(stroke, other), _stroke_distance(other, stroke)), index)
            for index, other in enumerate(remaining)
        ]
        cost, index = min(costs)
        total += cost / 2
        remaining.pop(index)
    return total / len(a)


def _extract_glyph(shape):
    if isinstance(shape, dict):
        return shape.get("glyph", [])
    return shape


def _glyphs(svg_text: str):
    polys = [
        [(float(a), float(b)) for a, b in re.findall(r"(-?[\d.]+),(-?[\d.]+)", row)]
        for row in re.findall(r'<polyline points="([^"]+)"', svg_text)
    ]
    if not polys:
        raise SvgCaptchaSolverError("SVG cek tidak berisi polyline digit")
    polys.sort(key=lambda pts: min(x for x, _ in pts))
    glyphs = []
    for pts in polys:
        left = min(x for x, _ in pts)
        if glyphs and left - max(x for g in glyphs for stroke in g for x, _ in stroke) > 14:
            glyphs.append([pts])
        elif glyphs:
            glyphs[-1].append(pts)
        else:
            glyphs.append([pts])
    return glyphs
